import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(16))
G.add_edges_from([(11,15), (3,15), (5,15)])
while True:
    try:
        nx.find_cycle(G)
        break
    except nx.NetworkXNoCycle:
        for u in range(16):
            for v in range(u+1, 16):
                if not G.has_edge(u, v):
                    G.add_edge(u, v)
                    try:
                        nx.find_cycle(G)
                        G.remove_edge(u, v)
                    except nx.NetworkXNoCycle:
                        pass
print("SATISFIABLE")
print(list(G.edges))
